<?php
declare(strict_types=1);
define('WP_CLI',true);require __DIR__.'/bootstrap.php';
use AISkillsHub\Core\Accounts\Crypto;
$service=$core->get('learning_subscriptions');$saved=$service->snapshot();wp_set_current_user($admin);$service->saveConfig(['enabled'=>true,'paused'=>false],$saved['revision']);$f=get_option('aish_p14_newsletter_race');$messages=[];add_filter('pre_wp_mail',static function($v,$mail)use(&$messages){$messages[]=$mail;return true;},PHP_INT_MAX,2);
try{p14_case('same_generation_digest_headers_and_live_public_gate',function()use($service,$core,$db,$f,$management,&$messages){
 $mail=$db->row('SELECT * FROM '.$db->table('notification_outbox')." WHERE recipient_user_id=%d AND template_key='newsletter_new' AND status IN ('queued','retry') ORDER BY id DESC LIMIT 1",[$f['b']]);p14_assert($mail!==null,'Retained owned queued new-resource digest exists');$payload=$core->get('account_store')->decryptPayload($mail);$issue=json_decode(get_post($payload['issue_id'])->post_content,true);$target=null;
 foreach($issue['refs']as$ref){if($ref['type']!=='skill')continue;$row=$db->row('SELECT s.id,s.status,tr.title,tr.slug FROM '.$db->table('skills').' s INNER JOIN '.$db->table('skill_translations')." tr ON tr.skill_id=s.id WHERE s.id=%d AND tr.locale='en_US'",[$ref['id']]);if($row&&$row['status']==='published'&&preg_match('/^(Experience QA|Browser QA)/',$row['title'])&&preg_match('/^(discovery|experience-browser)-[a-f0-9]{16}-/',$row['slug'])){$target=$row;break;}}
 p14_assert($target!==null,'Selected source is an owned Phase14 synthetic published Skill');$management->archiveSkill((int)$target['id'],p14_skill_revision((int)$target['id']));$table=$db->table('notification_outbox');$id=(int)$mail['id'];$db->execute("UPDATE $table SET available_at='1971-01-01 00:00:00' WHERE id=%d",[$id]);$filter=static function(string$sql)use($table,$id):string{if(str_starts_with($sql,"SELECT * FROM $table WHERE status IN ('queued','retry')")&&str_ends_with($sql,' LIMIT 1 FOR UPDATE'))return str_replace(' ORDER BY ',' AND id='.$id.' ORDER BY ',$sql);return$sql;};add_filter('query',$filter,PHP_INT_MAX);try{$core->get('account_mail_worker')->run();}finally{remove_filter('query',$filter,PHP_INT_MAX);}
 p14_assert($db->value("SELECT status FROM $table WHERE id=%d",[$id])==='accepted'&&count($messages)===1,'One actual intercepted digest accepted');$message=$messages[0];p14_assert(!str_contains($message['message'],$target['title']),'Skill archived after issue approval is removed at final send gate');$headers=is_array($message['headers'])?implode("\n",$message['headers']):$message['headers'];p14_assert(str_contains($headers,'List-Unsubscribe: <http://127.0.0.1:')&&!str_contains($headers,'List-Unsubscribe-Post:'),'HTTP local environment advertises valid cancel URL but never HTTPS-only one-click POST');$s=$service->rawState($f['b']);$token=Crypto::newsletterToken($f['b'],$s['generation'],$s['nonce'],$s['key_version'])['token'];p14_assert(str_contains($message['message'],$token),'Same-generation stable cancel token included');p14_assert(!str_contains($message['message'],'Private QA')&&!str_contains($message['message'],'rights_note'),'Internal notes not shared');
});}finally{$service->saveConfig(array_intersect_key($saved,['enabled'=>true,'paused'=>true]),$service->snapshot()['revision']);}
p14_report('Real retained owned digest rechecked after source withdrawal, with actual HTTP-safe cancellation headers and stable token; transport acceptance intercepted, no live SMTP or delivery');
